window.AUTH=window.AUTH||{};window.AUTH["25-5343"]={"d":"25-5343","id":"2026/25-5343","n":"Beaird v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Kendrick Beaird","date":"2026-06-30","url":"https://www.supremecourt.gov/DocketPDF/25/25-5343/415355/20260709161945466_25-5343BriefForPetitioner.pdf","side":"pet","n":105},{"k":"respondent","label":"Brief of respondent United States Supporting Vacatur","date":"2026-06-30","url":"https://www.supremecourt.gov/DocketPDF/25/25-5343/416115/20260709173938351_25-5343tsUnited_States-corrected.pdf","side":"res","n":52},{"k":"reply","label":"Reply of petitioner Kendrick Beaird","date":"2026-09-24","url":"https://www.supremecourt.gov/DocketPDF/25/25-5343/425587/20260924161808986_25-5343ReplyBriefForPetitioner.pdf","side":"pet","n":66}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"24","2":"15"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"ar":2,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"7, 8, 35, 39"}},{"t":"case","label":"Beckles v. United States","cite":"580 U.S. 256","y":2017,"id":"2016/15-8544","sc":1,"ar":1,"sum":"The Court held that its holding in Johnson v. US regarding the unconstitutionality of the residual clause in the Armed Criminal Career Act does not apply retroactively to identical language in the Sentencing Guidelines.","sumSrc":"Oyez","by":{"0":"25","1":"18","2":"16"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25","2":"16"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17"}},{"t":"case","label":"Bowles v. Seminole Rock & Sand Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"by":{"0":"1, 7, 8, 11-14, 23, 24, 34, 35, 37","1":"2, 6, 9, 11, 12, 14-19","2":"1, 2, 11, 12, 14-16, 18, 19, 21"}},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":2001,"id":"1990/90-5358","sc":1,"ar":3,"sum":"The court below misapplied the § 1B1.2(a) proviso.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"19, 25"}},{"t":"case","label":"Carter v. Welles-Bowen Realty, Inc.","cite":"736 F.3d 722","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/736/722/","by":{"0":"26, 41"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"1, 8, 23, 39, 43","2":"19"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Flood v. Kuhn","cite":"407 U.S. 258","y":1972,"id":"1971/71-32","sc":1,"sum":"He also cited Toolson , where the Court specifically held that the business of holding public baseball games for profit between professional clubs was not within the scope of federal antitrust laws. Justice Blackmun also noted that Federal Baseball and Toolson were frequently and favorably cited in other cases to establish the uniqueness of baseball’s exemption.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Ford Motor Credit Co. v. Milhollin","cite":"444 U.S. 555","y":1980,"id":"1979/78-1487","sc":1,"sum":"TILA does not mandate a general rule of disclosure for acceleration clauses.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"sum":"The Supreme Court, in a 7-2 ruling, reversed the appellate court and held that, under Booker , federal courts have the authority to set any reasonable sentence as long as they explain their reasoning. The Court made clear that Booker had removed the Guidelines from their earlier status as the primary determinate of a defendant's punishment, reaffirming the Guidelines' advisory status.","sumSrc":"Oyez","by":{"0":"4, 15, 25","1":"21","2":"10"}},{"t":"case","label":"Herrera v. Wyoming","cite":"587 U.S. 329","y":2019,"id":"2018/17-532","sc":1,"sum":"Wyoming’s statehood did not abrogate the Crow Tribe’s 1868 federal treaty right to hunt on the “unoccupied lands of the United States”; the lands of the Bighorn National Forest did not become categorically “occupied” when the forest was created.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"13, 42","2":"19"}},{"t":"case","label":"Immigr. & Naturalization Serv. v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"sum":"Justice Ruth Bader Ginsburg authored the Court's 7-2 majority opinion reversing the Fourth Circuit and affirming the sentence handed down by the trial judge. Ginsburg noted that the drug trafficking statute still had some minimum sentencing requirements, and expressed the Court's confidence that district courts could maintain reasonably uniform approaches to cocaine sentencing.","sumSrc":"Oyez","by":{"0":"29, 30","1":"27"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"ar":39,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1-3, 7, 8, 10, 12-14, 23, 24, 29-32, 34-37, 39-46","1":"2, 3, 9-20, 22, 24-27, 29","2":"1-3, 8, 11, 14-22"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"ar":16,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 2, 8, 11, 13, 14, 18, 21-23, 25, 29, 34, 42-44","1":"31","2":"1, 3, 8, 10, 11, 14, 15, 17-20, 23"}},{"t":"case","label":"Martin v. Occupational Safety and Health Review Comm’n","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"22","1":"4, 20, 27, 30"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"578 U.S. 189","y":2016,"id":"2015/14-8913","sc":1,"sum":"The Court held that an error in the application of the U.S. Sentencing Guidelines that results in the wrong Guideline range affected the defendant’s substantial rights.","sumSrc":"Oyez","by":{"0":"4, 25","1":"32","2":"15"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Peugh v. United States","cite":"569 U.S. 530","y":2013,"id":"2012/12-62","sc":1,"ar":1,"sum":"The Court found that using the U.S. Sentencing Guidelines at the time of the sentencing for a crime rather than at the time of the offense is a violation of the ex post facto clause.","sumSrc":"Oyez","by":{"0":"4, 25, 29","1":"21","2":"10, 15"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"sum":"The Court ruled that courts of appeals may apply a nonbinding presumption of reasonableness to within-Guidelines sentences. Justice Stephen Breyer wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"0":"30, 32, 33"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Rutherford v. United States","cite":"146 S. Ct. 1320","y":2026,"id":"2025/24-820","sc":1,"sum":"When Congress declines to make a sentencing amendment retroactive—as with the change to 18 U. S. C. §924(c)—the resulting sentencing disparity cannot serve as an “extraordinary and compelling” reason that warrants a sentence reduction under §3582(c)(1)(A)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18","2":"8-9, 12"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"ar":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"0":"34, 45","2":"18"}},{"t":"case","label":"Smith & Wesson Brands, Inc. v. Estados Unidos Mexicanos","cite":"605 U.S. 280","y":2025,"id":"2024/23-1141","sc":1,"sum":"Because Mexico’s complaint does not plausibly allege that the defendant gun manufacturers aided and abetted gun dealers’ unlawful sales of firearms to Mexican traffickers, the Protection of Lawful Commerce in Arms Act, 15 U. S. C. §7901(a)(3), bars the lawsuit.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"ar":60,"sum":"After petitioner Stinson pleaded guilty to a five-count indictment resulting from his robbery of a bank, the District Court sentenced him as a career offender under United States Sentencing Commission, Guidelines Manual §4B1.1, which requires, inter alia,that \"the instant offense of conviction [be] a crime of violence.\" The court found that Stinson's offense of possession of a firearm by a convicted felon, 18 U. S. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1-3, 7, 9-14, 23, 24, 27-29, 31, 32, 35, 36, 40, 42-44, 46","1":"2, 4, 6, 7, 11-27, 29, 30","2":"1, 2, 4, 6, 11, 12, 14, 17-22"}},{"t":"case","label":"SWANCC v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Talk Am. Inc. v. Mich. Bell Telephone Co.","cite":"564 U.S. 50","y":2011,"id":"2010/10-313","sc":1,"sum":"The Court held that federal law requires local telephone companies to allow new competitors in their markets to link to their existing networks through connecting wires at low, government-regulated rates.","sumSrc":"Oyez","by":{"0":"20, 39"}},{"t":"case","label":"United States v. Boler","cite":"115 F.4th 316","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/115/316/","by":{"0":"27"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"ar":21,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"1, 4, 6, 17, 25, 38, 44","1":"4, 21, 22","2":"10, 16, 17"}},{"t":"case","label":"United States v. Castillo","cite":"69 F.4th 648","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/69/648/","by":{"0":"2"}},{"t":"case","label":"United States v. Cramer","cite":"777 F.3d 597","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/777/597/","by":{"0":"33"}},{"t":"case","label":"United States v. Dupree","cite":"57 F.4th 1269","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/57/1269/","by":{"0":"2"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"19"}},{"t":"case","label":"United States v. Havis","cite":"927 F.3d 382","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/382/","by":{"0":"26"}},{"t":"case","label":"United States v. Maloid","cite":"71 F.4th 795","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/71/795/","by":{"0":"37"}},{"t":"case","label":"United States v. Martin","cite":"119 F.4th 410","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/119/410/","sum":"Recognizing that Fifth Circuit law foreclosed Mr. Beaird’s objection.","sumSrc":"brief:0","by":{"0":"10, 46","1":"28, 31"}},{"t":"case","label":"United States v. Moore","cite":"95 U.S. 760","y":1878,"id":"scdb/1877-140","sc":1,"sum":"This was an action in the Court of Claims by Andrew M. Moore against the United States, to recover certain pay which he alleged was due him as an officer in the navy. -","sumSrc":"Headnote (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Moses","cite":"23 F.4th 347","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/23/347/","by":{"0":"37, 38"}},{"t":"case","label":"United States v. Munoz","cite":"812 F.3d 809","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/812/809/","by":{"0":"33"}},{"t":"case","label":"United States v. Nasir","cite":"17 F.4th 459","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/17/459/","ar":1,"by":{"0":"2, 26, 27","2":"20"}},{"t":"case","label":"United States v. Rainford","cite":"110 F.4th 455","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/110/455/","by":{"0":"38"}},{"t":"case","label":"United States v. Riccardi","cite":"989 F.3d 476","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/989/476/","by":{"0":"2"}},{"t":"case","label":"United States v. Settles","cite":"530 F.3d 920","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/530/920/","by":{"0":"33"}},{"t":"case","label":"United States v. Smith","cite":"989 F.3d 575","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/989/575/","by":{"0":"27"}},{"t":"case","label":"United States v. Starks","cite":"861 F.3d 306","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/861/306/","by":{"0":"33"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"United States v. Vargas","cite":"74 F.4th 673","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/673/","by":{"0":"10, 37, 39, 40, 46","1":"3, 14, 28-30","2":"2, 11, 12"}},{"t":"case","label":"Page(s) United States v. White","cite":"97 F.4th 532","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/97/532/","ar":7,"by":{"0":"37"}},{"t":"case","label":"United States v. Zheng","cite":"113 F.4th 280","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/113/280/","by":{"0":"37, 38"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"sum":"1. Section 5438 of the Revised Statutes, which subjects to the penalties therein prescribed \"Every person who.. causes to be presented, for payment... any claim upon or against the Government of the United States,... knowing such claim to be.. fraudulent...,\" held applicable to contractors who, by collusive bidding, obtained contracts with municipalities and school districts of a State for work on federal Public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25-26"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’n","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Whitman v. United States","cite":"574 U.S. 1003","y":2014,"url":"https://supreme.justia.com/cases/federal/us/574/1003/","sc":1,"by":{"0":"26"}},{"t":"case","label":"Wisc. Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/274/","sc":1,"by":{"0":"26"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"21"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"4","1":"4, 21"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)","(c)","(b)(A)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"0":"5, 19","1":"7, 16, 5, 5","2":"8, 8"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"9","1":"3, 8"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(4)(1988)","(a)(4)","(a)(5)","(b)","(b)(1)","(b)(2)","(c)","(c)(2)","(f)(1)","(a)(6)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"16, 16, 30, 36, 38, 1, 4, 15-17, 25, 32, 39, 16, 4, 16, 17, 38, 6, 7, 17, 7, 17, 4, 25, 25","1":"21, 21","2":"5, 13, 13, 2, 3, 5, 10, 13, 2, 5, 15, 2, 6, 10, 13, 5, 8, 13, 5, 15"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)(1)(A)","(c)(1)(A)(i)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"18, 18","2":"8"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(a)(3)","(b)(3)","(f)(1)","(a)(2)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"head":"§3742. Review of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"15, 15, 15, 15","1":"21","2":"3, 10"}},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(a)"],"by":{"0":"47"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(a)","(b)(1)","(b)(1)(B)"],"stext":{"head":"§991. United States Sentencing Commission; establishment and purposes","paras":[[0,"(a) There is established as an independent commission in the judicial branch of the United States a United States Sentencing Commission which shall consist of seven voting members and one nonvoting member. The President, after consultation with representatives of judges, prosecuting attorneys, defense attorneys, law enforcement officials, senior citizens, victims of crime, and others interested in the criminal justice process, shall appoint the voting members of the Commission, by and with the advice and consent of the Senate, one of whom shall be appointed, by and with the advice and consent of the Senate, as the Chair and three of whom shall be designated by the President as Vice Chairs. At least 3 of the members shall be Federal judges selected after considering a list of six judges recommended to the President by the Judicial Conference of the United States. Not more than four of the members of the Commission shall be members of the same political party, and of the three Vice Chairs, no more than two shall be members of the same political party. The Attorney General, or the Attorney General's designee, shall be an ex officio, nonvoting member of the Commission. The Chair, Vice Chairs, and members of the Commission shall be subject to removal from the Commission by the President only for neglect of duty or malfeasance in office or for other good cause shown."],[0,"(b) The purposes of the United States Sentencing Commission are to—"],[1,"(1) establish sentencing policies and practices for the Federal criminal justice system that—"],[2,"(A) assure the meeting of the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code;"],[2,"(B) provide certainty and fairness in meeting the purposes of sentencing, avoiding unwarranted sentencing disparities among defendants with similar records who have been found guilty of similar criminal conduct while maintaining sufficient flexibility to permit individualized sentences when warranted by mitigating or aggravating factors not taken into account in the establishment of general sentencing practices; and"],[2,"(C) reflect, to the extent practicable, advancement in knowledge of human behavior as it relates to the criminal justice process; and"],[1,"(2) develop means of measuring the degree to which the sentencing, penal, and correctional practices are effective in meeting the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/991?type=usc&year=mostrecent&link-type=html"},"head":"§991. United States Sentencing Commission; establishment and purposes","tname":"Judiciary and Judicial Procedure","by":{"0":"19, 22, 30","1":"4, 6, 26-27, 26","2":"17, 16"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)","(a)(1)","(b)(1)","(o)","(p)","(s)","(t)","(x)","(a)(2)","(w)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"16, 19, 20, 27, 32, 36, 38, 16, 38, 5, 19, 4, 15, 16, 28, 4, 15, 5, 32, 5, 15, 19, 20, 22, 5, 18, 5, 6, 19, 20","1":"20, 20, 20, 20, 20, 20, 20, 20, 20","2":"12, 4, 8, 12, 4, 7, 8, 9, 18, 8, 9, 13, 8, 8, 9, 13, 16"}},{"t":"usc","label":"28 U.S.C. § 995","url":"https://www.law.cornell.edu/uscode/text/28/995","subs":["(b)","(d)"],"by":{"0":"20, 5, 19, 19, 20, 38"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(l)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"3, 5, 11, 14-18, 20, 21-23, 25, 32, 34, 36, 39","1":"4","2":"2-4, 7, 9, 14"}},{"t":"reg","label":"OTHER AUTHORITIES, 88 Fed. Reg. 60,536","url":"https://www.govinfo.gov/link/fr/88/60536","by":{"0":"44"}},{"t":"case","label":"Buford v. United States","cite":"532 U.S. 59","y":2001,"id":"2000/99-9073","sc":1,"ar":1,"sum":"The Court held that the Court of Appeals properly reviewed the District Court's \"''functional consolidation'\" decision deferentially \"[i]n light of the fact-bound nature of the legal decision, the comparatively greater expertise of the District Court, and the limited value of uniform court of appeals precedent.\" Rejecting Buford's arguments for de novo review, Justice Breyer wrote that \"the district court is in a better position than the appellate court to decide whether a particular set of individual circumstances demonstrates 'functional consolidation.'\".","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"United States v. Holman","cite":"171 F.4th 303","y":2026,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/171/303/","by":{"1":"26, 27, 31"}},{"t":"case","label":"United States v. McIntosh","cite":"124 F.4th 199","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/124/199/","by":{"1":"28, 31"}},{"t":"case","label":"United States v. Trumbull","cite":"114 F.4th 1114","y":2024,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/114/1114/","by":{"1":"28, 32"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"16"}},{"t":"usc","label":"5 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/5/801","subs":["(a)(1)(A)","(a)(3)(A)","(a)(4)","(b)(1)"],"by":{"1":"20, 20, 20, 20, 20, 21"}},{"t":"usc","label":"5 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/5/802","by":{"1":"21"}},{"t":"usc","label":"5 U.S.C. § 807","url":"https://www.law.cornell.edu/uscode/text/5/807","by":{"1":"20"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(a)"],"by":{"1":"32"}},{"t":"reg","label":"53 Fed. Reg. 15,530","url":"https://www.govinfo.gov/link/fr/53/15530","by":{"1":"6"}},{"t":"reg","label":"62 Fed. Reg. 38,598","url":"https://www.govinfo.gov/link/fr/62/38598","by":{"1":"6, 26"}},{"t":"case","label":"Am. Hosp. Ass’n v. Bowen","cite":"834 F.2d 1037","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/834/1037/","by":{"2":"6"}},{"t":"case","label":"Bullard v. United States","cite":"937 F.3d 654","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/654/","by":{"2":"21"}},{"t":"case","label":"Christensen v. Harris Cty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"FS Credit Opportunities Corp. v. Saba Capital Master Fund, Ltd.","cite":"608 U.S. 608","y":2026,"id":"2025/24-345","sc":1,"sum":"Section 47(b) of the Investment Company Act does not impliedly empower private parties to sue for rescission of contracts that allegedly violate the Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"Gamble v. United States","cite":"587 U.S. 678","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"Hein v. Freedom From Religion Foundation, Inc.","cite":"551 U.S. 587","y":2007,"id":"2006/06-157","sc":1,"sum":"By a 5-4 vote, the Court ruled that citizens do not have standing as taxpayers to bring Establishment Clause challenges against Executive Branch programs that are funded by appropriations for general administrative expenses.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Mohamad v. Palestinian Authority","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Nat’l Republican Senatorial Comm. v. FEC","cite":"146 S. Ct. 2404","y":2026,"url":"https://www.courtlistener.com/c/S.%20Ct./146/2404/","sc":1,"by":{"2":"19"}},{"t":"case","label":"Pacific Gas & Elec. Co. v. FPC","cite":"506 F.2d 33","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/506/33/","by":{"2":"7"}},{"t":"case","label":"Sandoval Argueta v. Bondi","cite":"137 F.4th 265","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/137/265/","by":{"2":"22"}},{"t":"case","label":"Trump v. Slaughter","cite":"146 S. Ct. 2283","y":2026,"id":"2025/25-332","sc":1,"sum":"The Federal Trade Commission’s for-cause removal provision, 15 U. S. C. §41, is contrary to the separation of powers enshrined in the Constitution.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"United States v. Martinez-Romero","cite":"817 F.3d 917","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/917/","by":{"2":"23"}},{"t":"case","label":"United States v. Redmond","cite":"965 F.3d 416","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/416/","by":{"2":"23"}},{"t":"case","label":"United States v. Ritchey","cite":"117 F.4th 762","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/117/762/","by":{"2":"23"}},{"t":"case","label":"United States v. Tanksley","cite":"848 F.3d 347","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/347/","by":{"2":"23"}},{"t":"case","label":"United States v. Taylor","cite":"2022 WL 2752602","y":2022,"court":"5th Cir. July 14","by":{"2":"23"}},{"t":"case","label":"Williams v. United States","cite":"503 U.S. 193","y":1992,"id":"1991/90-6297","sc":1,"ar":33,"sum":"Under the Sentencing Reform Act of 1984, the United States Sentencing Commission has promulgated Guidelines establishing sentencing ranges for different categories of federal offenses and defendants. The Act allows a district court to depart from a guideline range under certain circumstances, 18 U. S. C. §3553(b), and provides for limited appellate review of sentences, requiring a remand for resentencing if a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10, 11"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"2":"21"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(a)(15)"],"by":{"2":"8"}},{"t":"usc","label":"42 U.S.C. § 5846","url":"https://www.law.cornell.edu/uscode/text/42/5846","subs":["(a)(2)"],"by":{"2":"8"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(b)(1)(M)"],"by":{"2":"16"}}]};